BEGIN READ ONLY;
SET LOCAL statement_timeout = '5s';
SET LOCAL lock_timeout = '1s';
WITH evidence AS (SELECT c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,p.polname,p.polcmd,p.polpermissive,p.polroles,CASE WHEN p.oid IS NULL THEN false ELSE (0=ANY(p.polroles) OR EXISTS(SELECT 1 FROM pg_roles r WHERE r.oid=ANY(p.polroles) AND pg_has_role('authenticated',r.oid,'USAGE'))) END AS applies_authenticated,CASE WHEN p.oid IS NULL THEN false ELSE (0=ANY(p.polroles) OR EXISTS(SELECT 1 FROM pg_roles r WHERE r.oid=ANY(p.polroles) AND pg_has_role('anon',r.oid,'USAGE'))) END AS applies_anon,pg_get_expr(p.polqual,p.polrelid) AS using_expression,md5(coalesce(pg_get_expr(p.polqual,p.polrelid),'')) AS using_md5 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_policy p ON p.polrelid=c.oid AND p.polcmd IN ('r','*') WHERE n.nspname='public' AND c.relname IN ('components','inventory','admin_members') ORDER BY c.relname,p.polname LIMIT 50), packed AS (SELECT count(*) AS row_count,coalesce(jsonb_agg(to_jsonb(evidence)),'[]'::jsonb) AS rows FROM evidence), result AS (SELECT row_count,jsonb_build_object('status','OK','rows',rows) AS report FROM packed) SELECT CASE WHEN row_count>=50 OR octet_length(report::text)>8192 THEN jsonb_build_object('status','HOLD_LIMIT') ELSE report END AS evidence FROM result;
ROLLBACK;
